mapper.insert:
insert into code
    (CODE_ID
    , CODE_DC
    , CODE_VALUE
    , CODE_NM
    , SORT_ORD
    , USE_YN)
values ( #{codeId}
       , #{codeDc}
       , #{codeValue}
       , #{codeNm}
       , #{sortOrd}
       , #{useYn})

mapper.select:
SELECT DISTINCT CODE_DC
FROM code
WHERE CODE_ID = #{code}
